arguments.command:
cd /workspace && python3 - <<'EOF'
import subprocess, sys
try:
    p = subprocess.Popen([sys.executable, '-c', 'print(1)'], start_new_session=True)
    p.wait()
    print('setsid ok')
except Exception as e:
    print('setsid fail', e)
try:
    p = subprocess.Popen([sys.executable, '-c', 'print(2)'])
    p.wait()
    print('plain ok')
except Exception as e:
    print('plain fail', e)
import os
try:
    os.setsid()
except Exception as e:
    print('os.setsid fail', e)
EOF
